+}
+
+.app-actions {
+  display: flex;
+  justify-content: flex-end;
+  margin-block-start: var(--g-spacing-4);
+}
+
+.markdown-preview {
+  height: 100%;
+  overflow: auto;
+}
*** End Patch
PATCH
npm run build'

